      "translation": "sur le",
      "explanation": [
        "Idée principale : aufs est la contraction de auf das et signifie « sur le » devant un nom neutre, à la question Wohin? (vers où ?) : aufs Dach, aufs Bett, aufs Land.",
        "Aufs est une forme d'accusatif : auf + das Bett → aufs Bett. Au datif (Wo?), la forme aufs n'existe pas : auf dem Bett.",
        "On le trouve aussi dans des expressions figées : sich aufs Wochenende freuen (attendre le week-end avec impatience), aufs Beste (de la meilleure façon)."
      ],
      "examples": [
        {
          "de": "Ich lege das Handy aufs Bett.",
          "lv": "Je pose mon portable sur le lit."
        },
        {
          "de": "Am Wochenende fahren wir aufs Land.",
          "lv": "Le week-end, nous allons à la campagne."
        },
        {
          "de": "Die Katze springt aufs Sofa.",
          "lv": "Le chat saute sur le canapé."
        },
        {
          "de": "Er klettert aufs Dach.",
          "lv": "Il grimpe sur le toit."
        },
        {
          "de": "Ich freue mich aufs Wochenende.",
          "lv": "J'attends le week-end avec impatience."
        }
      ],
      "comparison": [
        {
          "word": "auf das",
          "meaning": "sur (forme complète)",
          "example": "Ich lege das Buch auf das Bett. – Je pose le livre sur le lit."
        },
        {
          "word": "auf dem",
          "meaning": "sur (datif)",
          "example": "Das Buch liegt auf dem Bett. – Le livre est sur le lit."
        },
        {
          "word": "auf den",
          "meaning": "sur (masculin)",
          "example": "Ich lege das Buch auf den Tisch. – Je pose le livre sur la table."
        }
      ],
      "tip": [
        "Aufs s'emploie uniquement avec un nom neutre à l'accusatif : das Bett → aufs Bett.",
        "Si das est accentué, on écrit la forme complète auf das."
      ],
      "important": [
        "Avec un nom masculin ou féminin, on n'emploie pas aufs : auf den Tisch, auf die Straße.",
        "Sans mouvement (Wo?), on dit auf dem Bett, et non 'aufs Bett'."
      ],
