        "Idée principale : einmal est un adverbe qui signifie une seule fois (Einmal pro Woche) ou un moment indéterminé — un jour, autrefois. Au début des contes, Es war einmal ... correspond au français « il était une fois ... ».",
        "Emplois : einmal + pro Tag/Woche/Monat (une fois par jour/semaine/mois), schon einmal (déjà une fois), noch einmal (encore une fois), nicht einmal (même pas).",
